// Apenas registro tipográfico; nenhum estado da aplicação é alterado.
if ('FontFace' in window && document.fonts) {
  [
    {
      weight: '600',
      family: 'Barlow Condensed',
      data: '',
    },
    {
      weight: '100 900',
      family: 'Montserrat',
      data: '',
    },
  ].forEach(({ family, weight, data }) => {
    try {
      const bytes = Uint8Array.from(atob(data), (character) => character.charCodeAt(0));
      const font = new FontFace(family, bytes, { weight, style: 'normal', display: 'swap' });
      document.fonts.add(font);
      font.load().catch(() => console.warn(`Fonte ${family} indisponível; usando fallback.`));
    } catch {
      /* Fallbacks definidos no tema mantêm a interface utilizável. */
    }
  });
}
/* Fim do registro visual de fontes JNG. */
